                            t.HasComment("Verbale di una policy di retention in una corsa: righe trovate, righe toccate, dove ha archiviato, e se e' fallita perche'. Una riga per (corsa, policy). Serve a tre cose che nessun'altra tabella copre: ritrovare le righe archiviate su storage, raccogliere gli errori senza fermare il motore, e leggere il report di dry-run prima di autorizzare l'esecuzione reale.");

                            t.HasCheckConstraint("ck_privacy_retention_runs_counts", "matched_rows >= 0 AND affected_rows >= 0 AND affected_rows <= matched_rows");

